-- Credit Ready (BCR Challenge 2) — Supabase schema
-- Run in Supabase SQL editor, then run seed.sql (generated by `npm run seed:sql`).

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------------------
-- Companies
-- ---------------------------------------------------------------------------
create table if not exists public.companies (
  id                            uuid primary key default gen_random_uuid(),
  name                          text not null,
  cui                           text not null unique,
  caen_code                     text not null,
  ceo_name                      text,
  city                          text,
  -- synthetic accounting data used for the cash-flow / DSCR estimate
  monthly_fixed_costs           numeric(14,2) not null default 0,
  existing_monthly_debt_service numeric(14,2) not null default 0,
  created_at                    timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- e-Factura documents (UBL 2.1 / RO_CIUS), issued and received
-- ---------------------------------------------------------------------------
create table if not exists public.e_invoices (
  id                   text not null,               -- "<direction>:<supplier CUI digits>:<number>"
  company_id           uuid not null references public.companies(id) on delete cascade,
  number               text not null,               -- cbc:ID
  direction            text not null check (direction in ('issued', 'received')),
  invoice_type_code    text not null default '380', -- 380 factură, 381 storno / credit note
  issue_date           date not null,               -- cbc:IssueDate
  due_date             date,                        -- cbc:DueDate
  supplier_name        text,                        -- AccountingSupplierParty
  supplier_cui         text,
  customer_name        text,                        -- AccountingCustomerParty
  customer_cui         text,
  tax_exclusive_amount numeric(14,2) not null,      -- LegalMonetaryTotal/TaxExclusiveAmount
  payable_amount       numeric(14,2),               -- LegalMonetaryTotal/PayableAmount
  currency             text not null default 'RON',
  paid_date            date,                        -- synthetic bank data (not part of e-Factura)
  source               text not null default 'synthetic' check (source in ('synthetic', 'xml-upload', 'supabase')),
  raw_xml              text,
  created_at           timestamptz not null default now(),
  primary key (company_id, id)
);
create index if not exists e_invoices_company_date_idx on public.e_invoices (company_id, issue_date);
create index if not exists e_invoices_type_idx on public.e_invoices (company_id, invoice_type_code);

-- ---------------------------------------------------------------------------
-- Sector benchmarks per CAEN code (p25 / median / p75)
-- ---------------------------------------------------------------------------
create table if not exists public.sector_benchmarks (
  caen_code          text primary key,
  label              text not null,
  companies          integer not null default 0,
  dso_p25            numeric, dso_median            numeric, dso_p75            numeric,
  top_client_p25     numeric, top_client_median     numeric, top_client_p75     numeric,
  credit_notes_p25   numeric, credit_notes_median   numeric, credit_notes_p75   numeric,
  seasonality_p25    numeric, seasonality_median    numeric, seasonality_p75    numeric,
  gross_margin_p25   numeric, gross_margin_median   numeric, gross_margin_p75   numeric,
  updated_at         timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Assessments (one row per saved evaluation / external quiz result)
-- ---------------------------------------------------------------------------
create table if not exists public.assessments (
  id             uuid primary key default gen_random_uuid(),
  company_id     uuid not null references public.companies(id) on delete cascade,
  quiz_answers   jsonb,
  quiz_score     integer,
  quiz_source    text not null default 'platform' check (quiz_source in ('platform', 'external')),
  investment     jsonb,
  legal_result   jsonb,
  legal_score    numeric,
  s_business     numeric,
  s_uman         numeric,
  s_investitie   numeric,
  final_score    numeric,
  status         text,
  kill_switch    boolean not null default false,
  metrics        jsonb,
  action_plan    jsonb,
  created_at     timestamptz not null default now()
);
create index if not exists assessments_company_idx on public.assessments (company_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Row Level Security
-- The Next.js API routes use the service-role key (bypasses RLS).
-- DEMO ONLY: if you run with the anon key, these permissive policies let the
-- prototype read/write. Replace them with per-user policies before production.
-- ---------------------------------------------------------------------------
alter table public.companies         enable row level security;
alter table public.e_invoices        enable row level security;
alter table public.sector_benchmarks enable row level security;
alter table public.assessments       enable row level security;

drop policy if exists demo_all_companies on public.companies;
drop policy if exists demo_all_invoices on public.e_invoices;
drop policy if exists demo_read_benchmarks on public.sector_benchmarks;
drop policy if exists demo_all_assessments on public.assessments;

create policy demo_all_companies   on public.companies         for all    using (true) with check (true);
create policy demo_all_invoices    on public.e_invoices        for all    using (true) with check (true);
create policy demo_read_benchmarks on public.sector_benchmarks for select using (true);
create policy demo_all_assessments on public.assessments       for all    using (true) with check (true);
